class Solution {
    static constexpr long long MOD = 1e9 + 7;
    long long pw(long long b, long long e) { long long r = 1; b %= MOD; while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; } return r; }
public:
    int countArrangements(vector<int>& A) {
        int n = A.size(), e = 0;
        for (int x : A) if (x % 2 == 0) e++;
        int o = n - e, g = o + 1;               // gaps around the odd numbers
        vector<long long> f(n + 2, 1), inv(n + 2, 1);
        for (int i = 1; i <= n + 1; i++) f[i] = f[i-1] * i % MOD;
        inv[n+1] = pw(f[n+1], MOD - 2);
        for (int i = n + 1; i > 0; i--) inv[i-1] = inv[i] * i % MOD;
        auto C = [&](int x, int y) -> long long { return (y < 0 || y > x) ? 0 : f[x] * inv[y] % MOD * inv[x-y] % MOD; };
        long long w = 0;
        for (int t = 0; 2 * t <= e; t++) {      // t gaps hold 2 evens, e - 2t gaps hold 1
            int ones = e - 2 * t;
            if (t + ones <= g) w = (w + C(g, t) * C(g - t, ones)) % MOD;
        }
        return (int)(f[o] * f[e] % MOD * w % MOD);
    }
};

