public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = nextInt(in);
        int[] A = new int[n];
        for (int i = 0; i < n; i++) A[i] = nextInt(in);
        System.out.println(new Solution().countArrangements(A));
    }
    private static int nextInt(DataInputStream in) throws IOException {
        int r = 0, b = in.read();
        while (b < '0' || b > '9') { if (b == '-') { b = in.read(); int v = 0; while (b >= '0' && b <= '9') { v = v * 10 + (b - '0'); b = in.read(); } return -v; } b = in.read(); }
        while (b >= '0' && b <= '9') { r = r * 10 + (b - '0'); b = in.read(); }
        return r;
    }
}
